// Fim dos Tempos · Aventura 4 · gerado por av4-terror-do-ceu.js
const fdtApi = game.modules.get("giriarpg-fim-dos-tempos")?.api;
if (!fdtApi?.testes) throw new Error("Fim dos Tempos: ative o módulo Giria T20 - Fim dos Tempos (Campanha) para usar esta macro.");
const fdtTestes = (lista) => fdtApi.testes.lista(lista);
const fdtTeste = async (ator, pericia, o = {}) => (await fdtTestes([{ ...o, ator, pericia }]))[0];
const fdtAplicar = fdtApi.testes.coletor();
const fdtEnviar = (dados) => fdtAplicar.enviar(dados);
try {
	await (async function macroElemental() {
		const torgo = game.actors.find((a) => a.getFlag("world", "fdtRole") === "torgo");
		if (!torgo) return ui.notifications.error("Torgo não encontrado (puxe a aventura do compêndio com a macro FdT · Puxar do compêndio).");
		const res = await foundry.applications.api.DialogV2.prompt({
			window: { title: "Elemental Elétrico" },
			content: `<p>Dano <b>mágico de eletricidade</b> que Torgo sofreria (antes da RD):</p>
				<div class="form-group"><label>Dano</label><input type="number" name="dano" value="0" autofocus></div>`,
			ok: { label: "Absorver", callback: (ev, button) => Object.fromEntries(new FormData(button.form)) }
		});
		if (!res) return;
		const cura = Math.floor((Number(res.dano) || 0) / 2);
		await fdtAplicar.curar(torgo, cura, `${torgo.name}: recupera ${cura} PV`);
		fdtEnviar({ content: `<h3>Elemental Elétrico</h3><p>A eletricidade é absorvida pelo relógio no peito de ${torgo.name}: ele <b>recupera ${cura} PV</b>.</p><p>Até o fim do próximo turno, pancadas e Olhar Elétrico causam <b>+1d6 de eletricidade</b> (marque <i>Carga elétrica</i> na pancada; use a rolagem \"Com carga elétrica\" do Olhar).</p>` });
	})();
} finally {
	await fdtAplicar.fim();
}
